namespace Sortiment.Core.Files;

/// <summary>
/// Identifies a stored file within an <see cref="IFileStorage"/>. Keys are generated by the storage implementation,
/// are opaque to everything else, and are never reused for different content.
/// </summary>
/// <remarks>
/// A key is a relative, portable path: one or more segments separated by <c>/</c>, where each segment contains only
/// ASCII letters, digits, <c>.</c>, <c>_</c> and <c>-</c>, and is neither <c>.</c> nor <c>..</c>. A key can therefore
/// be appended to a root directory or container name without escaping it.
/// </remarks>
public sealed record StorageKey
{
    /// <summary>
    /// The maximum length of a storage key.
    /// </summary>
    public const int MaxLength = 1024;

    /// <summary>
    /// Wraps a key generated by a storage implementation or read from storage.
    /// </summary>
    /// <param name="value">The key.</param>
    /// <exception cref="ArgumentException">
    /// <paramref name="value"/> is empty, longer than <see cref="MaxLength"/>, or not a relative path made of allowed
    /// segments.
    /// </exception>
    public StorageKey(string value)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(value);
        if (value.Length > MaxLength)
        {
            throw new ArgumentException($"A storage key can be at most {MaxLength} characters long.", nameof(value));
        }

        if (!value.Split('/').All(IsValidSegment))
        {
            throw new ArgumentException(
                "A storage key must be a relative path of segments separated by '/'. Segments can only contain ASCII letters, digits, '.', '_' and '-', and cannot be empty, '.' or '..'.",
                nameof(value));
        }

        Value = value;
    }

    /// <summary>
    /// Gets the key as a string.
    /// </summary>
    public string Value { get; }

    /// <inheritdoc />
    public override string ToString() => Value;

    private static bool IsValidSegment(string segment) =>
        segment.Length > 0
        && segment is not "." and not ".."
        && segment.All(character => char.IsAsciiLetterOrDigit(character) || character is '.' or '_' or '-');
}
